'use strict';

const PDFDocument = require('pdfkit');
const QRCode = require('qrcode');
const { inflateSync } = require('node:zlib');
const { canViewCase } = require('./auth');

const RESULTS = {
  VALID: 'เอกสารถูกต้อง', EXPIRED: 'เอกสารหมดอายุ',
  TAMPERED: 'ลายเซ็นไม่ถูกต้อง', NOT_FOUND: 'ไม่พบเอกสาร',
};

function validUntil(clock, serviceId, issuedAt) {
  const date = issuedAt.slice(0, 10);
  if (serviceId === 'SV-01') return clock.addDays(date, 89);
  const [year, month, day] = date.split('-').map(Number);
  const nextYear = year + 1;
  const leap = nextYear % 4 === 0 && (nextYear % 100 !== 0 || nextYear % 400 === 0);
  const anniversaryDay = month === 2 && day === 29 && !leap ? 28 : day;
  const anniversary = `${nextYear}-${String(month).padStart(2, '0')}-${String(anniversaryDay).padStart(2, '0')}`;
  return clock.addDays(anniversary, -1);
}

function verification(ctx, code) {
  const doc = ctx.db.get('SELECT * FROM documents WHERE verify_code=?', code);
  if (!doc) return { result: 'NOT_FOUND' };
  // Do not expose any fields from a record whose signature fails.
  if (!ctx.security.verifyDocumentSignature(doc)) return { result: 'TAMPERED' };
  return {
    result: ctx.clock.parts(ctx.clock.now()).date > doc.valid_until ? 'EXPIRED' : 'VALID',
    docNo: doc.doc_no,
    applicantMasked: ctx.security.maskName(doc.applicant),
    serviceId: doc.service_id,
    issuedAt: doc.issued_at,
    validUntil: doc.valid_until,
    signer: doc.signer,
  };
}

const verifyUrl = (req, code) => `${req.protocol}://${req.get('host')}/verify/${encodeURIComponent(code)}`;

async function makePdf(ctx, doc, url) {
  const qr = await QRCode.toBuffer(url, { type: 'png', errorCorrectionLevel: 'M', margin: 4, width: 240 });
  const service = ctx.db.get('SELECT name FROM services WHERE id=?', doc.service_id);
  const ascii = `docNo=${doc.doc_no} caseNo=${doc.case_no} verify=${doc.verify_code} validUntil=${doc.valid_until}`;
  return new Promise((resolve, reject) => {
    const pdf = new PDFDocument({ size: 'A4', margin: 45, compress: false,
      info: { Title: doc.doc_no, Subject: 'เอกสารดิจิทัลจำลอง เทศบาลนครตัวอย่าง', CreationDate: new Date(ctx.clock.parseIso(doc.issued_at)) } });
    const chunks = [];
    pdf.on('data', chunk => chunks.push(chunk));
    pdf.on('error', reject);
    // A PDF comment preserves the contract's exact machine-readable ASCII line.
    pdf.on('end', () => resolve(Buffer.concat([Buffer.concat(chunks), Buffer.from(`\n% ${ascii}\n`, 'ascii')])));
    pdf.font(inflateSync(Buffer.from(THAI_FONT, 'base64')));
    pdf.fontSize(20).text('เทศบาลนครตัวอย่าง', { align: 'center' });
    pdf.fontSize(14).text('เอกสารดิจิทัล · ลายเซ็นจำลอง', { align: 'center' }).moveDown();
    const rows = [
      `เลขเอกสาร: ${doc.doc_no}`, `เลขคำขอ: ${doc.case_no}`,
      `ผู้ยื่น: ${doc.applicant}`, `บริการ: ${doc.service_id} ${service ? service.name : ''}`,
      `วันออก: ${ctx.view.fmtDateTime(doc.issued_at)}`,
      `ใช้ได้ถึง: ${ctx.view.fmtDate(doc.valid_until)}`, `ผู้ลงนาม: ${doc.signer}`,
      `รหัสตรวจสอบ: ${doc.verify_code}`,
    ];
    rows.forEach(row => pdf.fontSize(13).text(row).moveDown(0.3));
    pdf.fontSize(10).text('ลายเซ็น HMAC-SHA256 (ตัวจำลอง)').text(doc.signature).moveDown();
    pdf.image(qr, { width: 130, height: 130 });
    pdf.fontSize(9).text(url, { link: url });
    pdf.moveDown().font('Helvetica').fontSize(7).text(ascii, { lineBreak: false });
    pdf.end();
  });
}

function register(app, ctx) {
  const { db, clock, ids, http, security, view, audit } = ctx;
  const e = view.esc;
  app.post('/api/officer/cases/:caseNo/issue', http.requireApi('officer'), (req, res) => {
    const outcome = db.tx(() => {
      const c = db.get('SELECT * FROM cases WHERE case_no=?', req.params.caseNo);
      if (!c) return { status: 404, code: 'NOT_FOUND', message: 'ไม่พบคำขอ' };
      if (c.issuer !== req.user.username || req.user.dept !== 'registry') {
        return { status: 403, code: 'FORBIDDEN', message: 'ไม่มีสิทธิ์ทำรายการนี้' };
      }
      if (c.status !== 'APPROVED' || c.doc_no) {
        return { status: 409, code: 'INVALID_STATE', message: 'สถานะคำขอไม่ถูกต้องสำหรับรายการนี้' };
      }
      const applicant = db.get('SELECT name FROM users WHERE username=?', c.applicant);
      const approver = db.get('SELECT name FROM users WHERE username=?', c.approver);
      if (!applicant || !approver) {
        return { status: 409, code: 'INVALID_STATE', message: 'สถานะคำขอไม่ถูกต้องสำหรับรายการนี้' };
      }
      const issuedAt = clock.nowIso();
      let code;
      do { code = security.newVerifyCode(); } while (db.get('SELECT 1 FROM documents WHERE verify_code=?', code));
      const doc = {
        doc_no: ids.nextDocNo(clock.parts(clock.parseIso(issuedAt)).be),
        case_no: c.case_no, verify_code: code, service_id: c.service_id,
        applicant: applicant.name, issued_at: issuedAt,
        valid_until: validUntil(clock, c.service_id, issuedAt), signer: approver.name,
      };
      doc.signature = security.signDocument(doc);
      db.run(`INSERT INTO documents(doc_no,case_no,verify_code,service_id,applicant,issued_at,valid_until,signer,signature)
        VALUES(?,?,?,?,?,?,?,?,?)`, doc.doc_no, doc.case_no, code, doc.service_id, doc.applicant,
      issuedAt, doc.valid_until, doc.signer, doc.signature);
      db.run("UPDATE cases SET status='COMPLETED', closed_at=?, doc_no=?, verify_code=?, owner=NULL WHERE case_no=?",
        issuedAt, doc.doc_no, code, c.case_no);
      const event = { event: 'ISSUE', caseNo: c.case_no, fromStatus: 'APPROVED', toStatus: 'COMPLETED', detail: doc.doc_no, time: issuedAt };
      audit.log(req.user, event);
      audit.timeline(c.case_no, { ...event, username: req.user.username });
      return { body: { docNo: doc.doc_no, verifyCode: code, status: 'COMPLETED' } };
    });
    if (outcome.body) return res.json(outcome.body);
    return http.apiError(res, outcome.status, outcome.code, outcome.message);
  });

  app.get('/api/documents/:docNo/pdf', http.requireApi('citizen', 'officer', 'head'), http.wrap(async (req, res) => {
    const doc = db.get('SELECT * FROM documents WHERE doc_no=?', req.params.docNo);
    const c = doc && db.get('SELECT * FROM cases WHERE case_no=?', doc.case_no);
    if (!doc || !c || !canViewCase(req.user, c)) return http.apiError(res, 404, 'NOT_FOUND', 'ไม่พบคำขอ');
    const pdf = await makePdf(ctx, doc, verifyUrl(req, doc.verify_code));
    res.set('Content-Type', 'application/pdf');
    res.set('Content-Disposition', `attachment; filename="${doc.doc_no}.pdf"`);
    res.set('Cache-Control', 'private, no-store');
    return res.send(pdf);
  }));

  app.get('/api/verify/:code', (req, res) => {
    const result = verification(ctx, req.params.code);
    res.set('Cache-Control', 'no-store');
    res.status(result.result === 'NOT_FOUND' ? 404 : 200).json(result);
  });

  app.get('/verify/:code', (req, res) => {
    const result = verification(ctx, req.params.code);
    let body = `<h1>ตรวจสอบเอกสารดิจิทัล</h1><p data-testid="verify-result" data-result="${result.result}" role="status">${RESULTS[result.result]}</p>`;
    if (result.result === 'VALID' || result.result === 'EXPIRED') {
      const service = db.get('SELECT name FROM services WHERE id=?', result.serviceId);
      body += `<dl>
        <dt>เลขเอกสาร</dt><dd data-testid="verify-doc-no">${e(result.docNo)}</dd>
        <dt>ผู้ยื่น</dt><dd data-testid="verify-applicant">${e(result.applicantMasked)}</dd>
        <dt>บริการ</dt><dd data-testid="verify-service">${e(result.serviceId)} ${e(service ? service.name : '')}</dd>
        <dt>วันออก</dt><dd>${view.dt(result.issuedAt, 'data-testid="verify-issued"')}</dd>
        <dt>ใช้ได้ถึง</dt><dd>${view.dd(result.validUntil, 'data-testid="verify-expires"')}</dd>
        <dt>ผู้ลงนาม</dt><dd data-testid="verify-signer">${e(result.signer)}</dd></dl>`;
    }
    res.set('Cache-Control', 'no-store');
    return view.page(req, res, { title: 'ตรวจสอบเอกสาร', body, status: result.result === 'NOT_FOUND' ? 404 : 200 });
  });

  app.post('/api/test/documents/:docNo/tamper', (req, res) => {
    const changed = db.run("UPDATE documents SET applicant=applicant || ' (แก้ไข)' WHERE doc_no=?", req.params.docNo);
    if (!changed.changes) return http.apiError(res, 404, 'NOT_FOUND', 'ไม่พบเอกสาร');
    return res.json({ ok: true });
  });
}

module.exports = { register, validUntil, verification };

